package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.file.*;import org.json.*;
public final class RoadSceneGpuInstrumentation extends SceneGpuInstrumentation {
 boolean[] correctedCommands;int correctedVisibleSamples;
 @Override int[] expected(NativeSceneSnapshot scene,NativeSceneDrawPlan plan,float[][] sources,double x,double y){lastSample="";int[] result=super.expected(scene,plan,sources,x,y);if(result!=null)for(int i=0;i<correctedCommands.length;i++)if(correctedCommands[i]&&lastSample.startsWith("command="+i+" ")){correctedVisibleSamples++;break;}return result;}

 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{
  byte[] raw=Files.readAllBytes(new File(getTargetContext().getFilesDir(),"road-scene-whole.nab").toPath());NativeSceneSnapshot scene=new NativeSceneSnapshot(raw);NativeSceneDrawPlan plan=new NativeSceneDrawPlan(scene.geometry(0));int indexed=0;for(int i=0;i<plan.count();i++)if(plan.draw(i).indexed)indexed++;ok(indexed==plan.count(),"Expected all synthetic draws indexed");
  NativeWorldScene world=new NativeWorldScene(scene.geometry(0));int corrected=0;for(int i=0;i<world.surfaceCount();i++)if(world.surface(i).mode==5||world.surface(i).mode==6)corrected++;ok(corrected==3,"Three corrected roads required");correctedCommands=new boolean[plan.count()];for(int i=0;i<plan.count();i++){NativeSceneDrawPlan.Draw draw=plan.draw(i);correctedCommands[i]=!draw.model&&(world.surface(draw.index).mode==5||world.surface(draw.index).mode==6);}startGl();live=true;String small=render(scene,240,160,240,160,"road-scene-240.png",false),large=render(scene,3840,2160,3240,2160,"road-scene-4k.png",false);ok(zeroChecks>0&&wallSkipEvaluations>0,"Indexed zero/skip path not sampled");endGl();live=false;startGl();live=true;ok(render(scene,240,160,240,160,null,false).equals(small),"Indexed context changed pixels");
  ok(correctedVisibleSamples>0,"No visible corrected-road samples");JSONObject report=new JSONObject();report.put("visible_corrected_road_sample_evaluations",correctedVisibleSamples);report.put("result","PASS_ANDROID_CORRECTED_ROAD_GLES");report.put("source_commands",plan.count());report.put("corrected_roads",corrected);report.put("indexed_commands",indexed);report.put("renderer",renderer);report.put("api",Build.VERSION.SDK_INT);report.put("source_pixel_checks",checks);report.put("zero_index_evaluations",zeroChecks);report.put("wall_skip_evaluations",wallSkipEvaluations);report.put("native_rgba_sha256",small);report.put("four_k_frame_sha256",large);report.put("synthetic_materials",true);report.put("per_row_palette_variants",160);report.put("context_recreated",true);report.put("full_scene",false);report.put("real_time_pacing",false);try(FileOutputStream out=getTargetContext().openFileOutput("road-scene-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){android.util.Log.e("NFSUGSceneGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
